namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was updated."),
            CreateNotification("You have a new follower."),
        });
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given timestamp.</summary>
    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }

    /// <summary>Simulate a new notification arriving roughly every 10 seconds.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            // ~30 % chance each poll cycle adds a notification, keeping the demo interesting.
            if (Random.Shared.Next(0, 3) == 0)
            {
                var messages = new[]
                {
                    "New comment on your post.",
                    "Someone liked your photo.",
                    "System maintenance scheduled.",
                    "You earned a badge!",
                    "Your export is ready to download.",
                };
                _notifications.Add(
                    CreateNotification(messages[Random.Shared.Next(messages.Length)]));
            }
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow.AddTicks(_nextId));
    }
}

